export default class Handshake {
  transport: TransportConnection;
  callback: (HandshakePayload) => void;
  onMessage: Function;
  onClosed: Function;

  constructor(
    transport: TransportConnection,
    callback: (HandshakePayload) => void,
  ) {
    this.transport = transport;
    this.callback = callback;
    this.bindListeners();
  }

  close() {
    this.unbindListeners();
    this.transport.close();
  }

  private bindListeners() {
    this.onMessage = (m) => {
      this.unbindListeners();

